#include <iostream>


using namespace std;


bool prime(int n){if(n<2)return false;for(int i=2;i*i<=n;i++)if(n%i==0)return false;return true;}


int main(){int m,n;cin>>m>>n;bool found=false;for(int x=m;x<=n;x++){if(prime(x)){if(found)cout<<' ';cout<<x;found=true;}}


if(!found)cout<<'-';cout<<'\n';}
